// Fetches one export/ bundle (generated by data-pipeline/export/build_bundle.py) as a static
// JSON asset from public/data/. No backend — see root CLAUDE.md phasing, this is still Phase 2.

export function codepointHex(char) {
  return char.codePointAt(0).toString(16).padStart(5, '0')
}

export async function loadKanjiBundle(char) {
  const res = await fetch(`/data/${codepointHex(char)}.json`)
  if (!res.ok) {
    throw new Error(`No data for "${char}" (${res.status})`)
  }
  return res.json()
}

// element -> [{codepoint, character}, ...] for every OTHER kanji where that element was also
// marked useful — built by data-pipeline/export/build_component_index.py. Fetched once, cached
// module-level (~586KB for the whole dataset — small enough to just hold in memory).
let componentIndexPromise = null

export function loadComponentIndex() {
  if (!componentIndexPromise) {
    componentIndexPromise = fetch('/data/_index.json').then((res) => {
      if (!res.ok) throw new Error(`Failed to load component index (${res.status})`)
      return res.json()
    })
  }
  return componentIndexPromise
}
